// Draft: CSV/Markdown export for notes. Not wired up yet — still working on it.
export function toCsv(notes) {
  const header = 'id,title,createdAt';
  const rows = notes.map(n => [n.id, JSON.stringify(n.title), n.createdAt].join(','));
  return [header, ...rows].join('\n');
}

export function toMarkdown(notes) {
  return notes.map(n => `## ${n.title}\n\n${n.body ?? ''}\n`).join('\n');
}

